PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS pp_merchants(id TEXT PRIMARY KEY,slug TEXT NOT NULL UNIQUE,legal_name TEXT NOT NULL,trading_name TEXT NOT NULL,currency TEXT NOT NULL DEFAULT 'ZAR',tax_rate REAL NOT NULL DEFAULT 15,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS pp_branches(id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL REFERENCES pp_merchants(id) ON DELETE CASCADE,name TEXT NOT NULL,address TEXT,active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS pp_staff(id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL REFERENCES pp_merchants(id) ON DELETE CASCADE,name TEXT NOT NULL,email TEXT,phone TEXT,role TEXT NOT NULL CHECK(role IN('owner','manager','supervisor','cashier')),pin_salt TEXT,pin_hash TEXT,disabled INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX IF NOT EXISTS pp_staff_email ON pp_staff(merchant_id,email) WHERE email IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS pp_staff_phone ON pp_staff(merchant_id,phone) WHERE phone IS NOT NULL;
CREATE TABLE IF NOT EXISTS pp_sessions(id TEXT PRIMARY KEY,staff_id TEXT NOT NULL REFERENCES pp_staff(id) ON DELETE CASCADE,token_hash TEXT NOT NULL UNIQUE,expires_at TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,revoked_at TEXT);
CREATE TABLE IF NOT EXISTS pp_devices(id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL REFERENCES pp_merchants(id) ON DELETE CASCADE,branch_id TEXT REFERENCES pp_branches(id),label TEXT,platform TEXT,enrolled_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,revoked_at TEXT);
CREATE TABLE IF NOT EXISTS pp_customers(id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL REFERENCES pp_merchants(id) ON DELETE CASCADE,name TEXT NOT NULL,phone TEXT,email TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS pp_products(id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL REFERENCES pp_merchants(id) ON DELETE CASCADE,sku TEXT NOT NULL,barcode TEXT,name TEXT NOT NULL,price_minor INTEGER NOT NULL CHECK(price_minor>=0),active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(merchant_id,sku),UNIQUE(merchant_id,barcode));
CREATE TABLE IF NOT EXISTS pp_inventory(branch_id TEXT NOT NULL REFERENCES pp_branches(id) ON DELETE CASCADE,product_id TEXT NOT NULL REFERENCES pp_products(id) ON DELETE CASCADE,on_hand INTEGER NOT NULL DEFAULT 0 CHECK(on_hand>=0),updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(branch_id,product_id));
CREATE TABLE IF NOT EXISTS pp_sales(id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL REFERENCES pp_merchants(id),branch_id TEXT NOT NULL REFERENCES pp_branches(id),staff_id TEXT NOT NULL REFERENCES pp_staff(id),customer_id TEXT REFERENCES pp_customers(id),status TEXT NOT NULL CHECK(status IN('pending','paid','void','refunded')),payment_method TEXT NOT NULL,subtotal_minor INTEGER NOT NULL,tax_minor INTEGER NOT NULL,total_minor INTEGER NOT NULL,external_payment_id TEXT,idempotency_key TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,paid_at TEXT,UNIQUE(merchant_id,idempotency_key));
CREATE TABLE IF NOT EXISTS pp_sale_items(id TEXT PRIMARY KEY,sale_id TEXT NOT NULL REFERENCES pp_sales(id) ON DELETE CASCADE,product_id TEXT REFERENCES pp_products(id),description TEXT NOT NULL,quantity INTEGER NOT NULL CHECK(quantity>0),unit_price_minor INTEGER NOT NULL,line_total_minor INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS pp_payment_events(id TEXT PRIMARY KEY,sale_id TEXT NOT NULL REFERENCES pp_sales(id) ON DELETE CASCADE,provider TEXT NOT NULL,provider_event_id TEXT NOT NULL,event_type TEXT NOT NULL,verified INTEGER NOT NULL DEFAULT 0,payload_json TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(provider,provider_event_id));
CREATE TABLE IF NOT EXISTS pp_audit_log(id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL REFERENCES pp_merchants(id),staff_id TEXT REFERENCES pp_staff(id),device_id TEXT REFERENCES pp_devices(id),action TEXT NOT NULL,entity_type TEXT,entity_id TEXT,metadata_json TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS pp_sales_merchant_created ON pp_sales(merchant_id,created_at);
CREATE INDEX IF NOT EXISTS pp_sales_branch_created ON pp_sales(branch_id,created_at);
CREATE INDEX IF NOT EXISTS pp_audit_merchant_created ON pp_audit_log(merchant_id,created_at);
CREATE INDEX IF NOT EXISTS pp_sessions_token ON pp_sessions(token_hash);
